/**
 * Example catalogue — the single source for BOTH:
 *   • supabase/seed.sql   (generated by `npm run seed:generate`)
 *   • demo mode           (used when Supabase keys are not set yet)
 * Prices here are in RUPEES for readability; they are converted to paise.
 * The owner replaces all of this from the admin panel later.
 */
import type { ProductType } from "@/lib/types";

/** Readable, stable UUIDs so seed rows never change between runs. */
export function seedId(kind: number, n: number): string {
  return `${kind}0000000-0000-4000-8000-${String(n).padStart(12, "0")}`;
}

